import * as React from "react";
import { useState } from "react";
import { RadioButton, RadioButtonProps } from "./RadioButton";


export interface RadioButtonOption {
  id: string;
  name: string;
  label: string;
  value: string;
  disabled?: boolean;
}

export interface RadioButtonGroupProps {
  /**
   * Array of radio button options to render.
   */
  options: RadioButtonOption[];

  /**
   * The value of the radio button that should be selected by default
   * when the component first renders. It must match one of the option values.
   */
  defaultValue?: string;

  /**
   * Identify the radio button value.
   */
  value?: string;

  /**
   * Callback when any checkbox in the group changes.
   */
  onChange?: (selected: string) => void;
    /**
   * Hex code that determines the background colour of the field when it is checked.
   */
  colour?: RadioButtonProps["colour"];

  /**
   * Layout direction for displaying radion button
   */
  layout?: "vertical" | "horizontal";
  /**
   * Shared error message for the group.
   */
  errorText?: string;
  /**
   * Optional className for wrapper div.
   */
  className?: string;

}


export const RadioButtonGroup: React.FC<RadioButtonGroupProps> = ({
  options,
  value,
  colour,
  layout,
  errorText = "",
  className = "",
  defaultValue,
  onChange
}) => {

  // Only use internal state if value is not provided
  const [internalValue, setInternalValue] = useState(defaultValue || "");
  const isControlled = value !== undefined;
  const selectedValue = isControlled ? value : internalValue;

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = event.target.value;
    if (!isControlled) {
      setInternalValue(newValue);
    }
    if (onChange) {
      onChange(newValue);
    }
  };

  /*const [selectedValue, setSelectedValue] = useState(defaultValue || "");

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value;
    setSelectedValue(value);
    if (onChange) {
      onChange(value);
    }
  };
  */

  return (
    <div className={`radion-button-group-wrapper ${layout} ${className}`}>
      {options.map((option) => (
        <RadioButton
            key={option.value}
            id={option.value}
            colour={colour}
            label={option.label}
            name={option.name}
            value={option.value}
            checked={selectedValue === option.value}
            // checked={value === option.value}
            onChange={handleChange}
            disabled={option.disabled}
        />

      ))}

      {errorText && (
        <div className="group-error-text">
          <p className="error-text">
            <span>{errorText}</span>
          </p>
        </div>
      )}
    </div>
  );
};